// Combine/Collect merge independent Results without short-circuiting: unlike Bind, a failure in
// one input does not hide diagnostics from the others, so a pipeline reports every problem it
// finds in a single pass instead of one at a time across repeated builds.
internal static class Result
{
    public static Result<(A, B)> Combine<A, B>(Result<A> first, Result<B> second)
        where A : IEquatable<A>
        where B : IEquatable<B>
    {
        if (first.IsSuccess && second.IsSuccess)
        {
            return Result<(A, B)>.Success((GetValue(first), GetValue(second)));
        }

        var diagnostics = MergeDiagnostics(first.Diagnostics, second.Diagnostics);

        // A failing input can itself be default(Result<T>) (failure, no diagnostics), so the
        // merge can end up empty; default(Result<(A, B)>) is that same no-diagnostics failure.
        return diagnostics.IsEmpty
            ? default
            : Result<(A, B)>.Failure(diagnostics);
    }

    public static Result<(A, B, C)> Combine<A, B, C>(Result<A> first, Result<B> second, Result<C> third)
        where A : IEquatable<A>
        where B : IEquatable<B>
        where C : IEquatable<C>
    {
        if (first.IsSuccess && second.IsSuccess && third.IsSuccess)
        {
            return Result<(A, B, C)>.Success((GetValue(first), GetValue(second), GetValue(third)));
        }

        var diagnostics = MergeDiagnostics(first.Diagnostics, second.Diagnostics, third.Diagnostics);

        return diagnostics.IsEmpty
            ? default
            : Result<(A, B, C)>.Failure(diagnostics);
    }

    // Every entry must be a success for Collect to succeed; a failing entry (including a
    // default(Result<T>), which has no diagnostics) fails the whole collection. Empty input
    // is not a failure: it collects to a success holding an empty array.
    public static Result<EquatableArray<T>> Collect<T>(IEnumerable<Result<T>> results)
        where T : IEquatable<T>
    {
        List<DiagnosticInfo>? diagnostics = null;
        var values = new List<T>();
        var anyFailure = false;

        foreach (var result in results)
        {
            if (result.IsSuccess)
            {
                values.Add(GetValue(result));
            }
            else
            {
                anyFailure = true;

                foreach (var diagnostic in result.Diagnostics)
                {
                    diagnostics ??= new List<DiagnosticInfo>();
                    diagnostics.Add(diagnostic);
                }
            }
        }

        if (!anyFailure)
        {
            return Result<EquatableArray<T>>.Success(EquatableArray<T>.FromOwnedArray(values.ToArray()));
        }

        return diagnostics is null
            ? default
            : Result<EquatableArray<T>>.Failure(EquatableArray<DiagnosticInfo>.FromOwnedArray(diagnostics.ToArray()));
    }

    private static T GetValue<T>(Result<T> result)
        where T : IEquatable<T>
    {
        return result.Match(value => value, _ => default(T)!);
    }

    private static EquatableArray<DiagnosticInfo> MergeDiagnostics(params EquatableArray<DiagnosticInfo>[] sets)
    {
        var diagnostics = new List<DiagnosticInfo>();

        foreach (var set in sets)
        {
            foreach (var diagnostic in set)
            {
                diagnostics.Add(diagnostic);
            }
        }

        return diagnostics.Count == 0
            ? default
            : EquatableArray<DiagnosticInfo>.FromOwnedArray(diagnostics.ToArray());
    }
}
